    """模拟执行步骤，验证最终所有盘从 start 移到 end 且过程中不违反规则。"""
    height = 4
    start, end = 1, 3
    pegs = {1: list(range(height, 0, -1)), 2: [], 3: []}
    for a, b in hanoi(height, start, end):
        assert pegs[a], f"peg {a} 为空，无法移动"
        disk = pegs[a].pop()
        if pegs[b]:
            assert disk < pegs[b][-1], "大盘不能放在小盘上"
